<?php
declare(strict_types=1);
require_once __DIR__.'/../config/bootstrap.php';require_once __DIR__.'/../config/governance.php';require_once __DIR__.'/../config/privacy.php';$user=require_login($pdo);$pageTitle='Identität & Alter';$error='';$reason=verification_reason($pdo);
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){require_csrf();try{if($reason!==null)throw new DomainException($reason);if(post_string('consent')!=='1')throw new InvalidArgumentException('Bitte die datensparsame Prüfung und Aufbewahrungsfrist bestätigen.');verification_submit($pdo,(int)$user['id'],$_FILES['documents']??[]);redirect('/user/verification.php?submitted=1');}catch(InvalidArgumentException|DomainException $e){http_response_code(422);$error=$e->getMessage();}}
$q=$pdo->prepare('SELECT id,status,identity_confirmed,age_confirmed,decision_reason,created_at,expires_at,purged_at FROM market_verification_requests WHERE user_id=? ORDER BY id DESC LIMIT 20');$q->execute([$user['id']]);$requests=$q->fetchAll();include __DIR__.'/../includes/header.php';?>
<main class="container"><div class="page-heading"><p class="eyebrow">Getrennte Nachweise</p><h1>Identität und Alter.</h1><p>Eine bestätigte Identität ist keine Bestätigung weiterer rechtlicher Erwerbsberechtigungen. Der allgemeine Markt schaltet dadurch keine regulierten Waren frei.</p></div><?php if($error):?><p class="notice error"><?=h($error)?></p><?php endif;?><?php if(isset($_GET['submitted'])):?><p class="notice success">Dein Antrag wurde verschlüsselt zur Prüfung gespeichert.</p><?php endif;?>
<section class="panel"><?php if($reason):?><h2>Prüfung derzeit nicht verfügbar</h2><p><?=h($reason)?></p><p>Bitte keine Dokumente über Nachrichten oder öffentliche Produktbilder senden.</p><?php else:?><h2>Prüfantrag</h2><p>Nur erforderliche Angaben zeigen; nicht benötigte Dokumentenfelder dürfen geschwärzt werden. Bilder werden neu codiert und außerhalb des Webroots verschlüsselt gespeichert. Die Aufbewahrungsfrist beträgt <?=(int)site_setting($pdo,'verification_retention_days','0')?> Tage ab Antrag. Danach werden die Dateien automatisiert gelöscht; die minimale Prüfentscheidung bleibt nachvollziehbar.</p><form method="post" enctype="multipart/form-data" class="form-grid"><?=csrf_field()?><label class="field">Dokumentbilder<input type="file" name="documents[]" accept="image/jpeg,image/png" multiple required><small>Ein bis drei JPEG-/PNG-Dateien bis je 5 MiB und 12 Megapixel, keine PDFs.</small></label><label><input type="checkbox" name="consent" value="1" required> Ich beantrage die beschriebene Prüfung, habe die Verifikations- und Datenschutzhinweise gelesen und kenne die angegebene Aufbewahrungsfrist.</label><button class="button" type="submit">Verschlüsselt einreichen</button></form><?php endif;?></section>
<section class="panel"><h2>Deine Anträge</h2><?php foreach($requests as $request):?><article><h3>Antrag #<?=(int)$request['id']?></h3><p>Status <?=h($request['status'])?> · Identität <?=$request['identity_confirmed']?'bestätigt':'nicht bestätigt'?> · Alter <?=$request['age_confirmed']?'bestätigt':'nicht bestätigt'?></p><?php if($request['decision_reason']):?><p><?=nl2br(h($request['decision_reason']))?></p><?php endif;?><p>Dokumentenfrist <?=h($request['expires_at'])?> UTC · <?=$request['purged_at']?'Dateien gelöscht':'Dateien innerhalb der Frist geschützt'?></p></article><?php endforeach;?><?php if(!$requests):?><p>Noch keine Anträge.</p><?php endif;?></section></main><?php include __DIR__.'/../includes/footer.php';?>
